INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_15_6', 'proj_15', 'Bab 6: Pembuktian Dan Analisis Komparatif — Jejak Pengembara Parahyangan', 'Menyusun Kembali Cerita', 'Hari-hari berikutnya dihabiskan di depan layar monitor dan tumpukan buku referensi. Kami membandingkan tulisan tangan di buku harian dengan arsip otentik milik Perpustakaan Nasional dan Arsip Daerah.' || char(10) || '' || char(10) || 'Metode pengujian tingkat keasaman kertas (pH test) dan analisis gaya bahasa mengonfirmasi bahwa naskah ini memang ditulis secara berkala antara tahun 1928 hingga 1935 oleh seorang juru ketik keraton yang juga menjadi anggota rahasia pergerakan.' || char(10) || '' || char(10) || '"Setiap paragraf di sini memiliki ritme narasi yang jujur," catatku dalam log revisi studio. "Penulisnya tidak berusaha mendramatisir keadaan. Dia mencatat harga beras, harga tiket kereta, kecemasan warga saat patroli malam, hingga obrolan hangat di warung kopi."' || char(10) || '' || char(10) || 'Inilah kekuatan dari penulisan berbasis fakta dan pengalaman nyata manusia. Tulisan seperti ini memiliki ''jiwa'' yang tidak akan pernah bisa ditiru oleh mesin atau algoritma generatif buatan.', 6, 'final', 'Kirana Maharani', '2026-09-16T06:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_15_7', 'proj_15', 'Bab 7: Refleksi Dan Rekonstruksi Naskah — Jejak Pengembara Parahyangan', 'Menuju Draf Final', 'Proses kolaborasi penulisan naskah ini telah memasuki tahap penyuntingan akhir. Draf bab demi bab kami kaji bersama di ruang kerja Studio Buku. Setiap anggota tim memberikan catatan kritis pada papan bab.' || char(10) || '' || char(10) || '"Bagian deskripsi latar di Bab 4 perlu kita pertebal," saran Siti. "Pembaca harus bisa merasakan dinginnya angin lereng bukit dan bau tanah basah saat hujan menyiram lereng."' || char(10) || '' || char(10) || '"Setuju," sahut Broto. "Dan di Bab 5, kutipan dari buku catatan harian harus kita tampilkan dalam format khusus agar otentisitase naskah aslinya tetap terjaga."' || char(10) || '' || char(10) || 'Proses ''nulis bareng'' ini membuktikan bahwa dua atau tiga kepala yang berpikir bersama mampu melahirkan karya yang jauh lebih kaya, berkedalaman, dan bernyawa dibandingkan penulisan tunggal yang terisolasi.', 7, 'review', 'Kirana Maharani', '2026-09-16T07:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_15_8', 'proj_15', 'Bab 8: Epilog Dan Harapan Baru — Jejak Pengembara Parahyangan', 'Warisan Untuk Masa Depan', 'Naskah buku ini akhirnya siap dipersembahkan kepada publik. Dari sebuah dokumen kusam berstempel merah pudar di lemari tua, kini telah menjelma menjadi sebuah karya buku utuh yang siap dibaca oleh ribuan generasi mendatang.' || char(10) || '' || char(10) || 'Sejarah dan karya literasi bukan sekadar deretan angka tahun atau nama tokoh yang harus dihafalkan. Literatur adalah jembatan emosional yang menghubungkan rasa kemanusiaan kita dengan orang-orang yang pernah hidup, berjuang, dan bermimpi di atas tanah yang sama puluhan tahun lalu.' || char(10) || '' || char(10) || 'Terima kasih kepada seluruh tim co-author, peneliti lapangan, dan pembaca setia di Studio Buku yang telah mengawal perjalanan naskah ini dari draf awal hingga terbit.' || char(10) || '' || char(10) || 'Semoga naskah ini menjadi penyala api literasi dan inspirasi bagi lahirnya buku-buku kolaboratif berikutnya di Indonesia.', 8, 'review', 'Kirana Maharani', '2026-09-16T08:00:00.000Z');
